// Build conversation context for AI agent
const lead = $('Get Lead Context').first().json;
const history = $('Get Conversation History').all().map(h => h.json);
const incomingMessage = $('Webhook - Incoming Message').first().json.message;

const conversationHistory = history.map(h => 
  `${h.role}: ${h.message}`
).join('\n');

return [{
  json: {
    lead: lead,
    incoming_message: incomingMessage,
    conversation_history: conversationHistory,
    lead_stage: lead.stage,
    lead_score: lead.score
  }
}];

