// Parse AI response and extract structured data
const response = $input.first().json;
const fullText = response.choices?.[0]?.message?.content || response.text || '';

// Try to extract JSON from response
let suggestedStage = '';
let followUpHours = 24;
let actionItems = [];
let cleanMessage = fullText;

const jsonMatch = fullText.match(/\{[\s\S]*"suggested_stage"[\s\S]*\}/);
if (jsonMatch) {
  try {
    const parsed = JSON.parse(jsonMatch[0]);
    suggestedStage = parsed.suggested_stage || '';
    followUpHours = parsed.follow_up_hours || 24;
    actionItems = parsed.action_items || [];
    cleanMessage = fullText.replace(jsonMatch[0], '').trim();
  } catch(e) {}
}

const lead = $('Build AI Context').first().json.lead;

return [{
  json: {
    lead_id: lead.lead_id,
    response_message: cleanMessage,
    suggested_stage: suggestedStage,
    follow_up_hours: followUpHours,
    action_items: actionItems,
    phone: lead.phone,
    email: lead.email,
    name: lead.name
  }
}];

// Filter leads that need follow-up
const leads = $input.all();
const now = new Date();
const needsFollowUp = [];

const followUpMessages = {
  'contacted': 'Oi {name}! Tudo bem? Vi que voce demonstrou interesse no nosso curso de Bar Staff. Ficou com alguma duvida? Estou aqui para ajudar! As proximas turmas estao quase lotando.',
  'qualified': 'Oi {name}! Passando para lembrar que temos vagas abertas para a proxima turma. Ja pensou em garantir sua vaga? Posso te enviar os detalhes de pagamento.',
  'proposal_sent': 'Oi {name}! Voce recebeu as informacoes do curso? Gostaria de saber se ficou com alguma duvida. Lembre-se que o preco early bird e por tempo limitado!',
  'negotiation': 'Oi {name}! Como vai? Conseguiu pensar sobre o curso? Se tiver qualquer duvida, estou a disposicao. Posso tambem agendar uma call rapida para conversarmos!'
};

for (const lead of leads) {
  const data = lead.json;
  if (!data.next_follow_up || data.stage === 'enrolled' || data.stage === 'lost' || data.stage === 'completed' || data.stage === 'alumni') continue;

  const followUpTime = new Date(data.next_follow_up);
  if (now >= followUpTime && data.phone) {
    const template = followUpMessages[data.stage] || followUpMessages['contacted'];
    needsFollowUp.push({
      json: {
        lead_id: data.lead_id,
        name: data.name,
        phone: data.phone,
        stage: data.stage,
        message: template.replace('{name}', data.name)
      }
    });
  }
}

return needsFollowUp.length > 0 ? needsFollowUp : [{ json: { skip: true } }];
